// Generate Gold Noise image

// precision lowp    float;
// precision mediump float;
// precision highp   float;



void mainImage(out vec4 C, in vec2 P)
{
    vec2 c = P/iResolution.xy;

    float z = fract(iTime);                    // fractional base seed

    // three uncorrelated pairs.
    vec2 n[3];
    n[0] = boxmuller(vec2(randf(P, z+0.1), randf(P, z+0.2)));
    n[1] = boxmuller(vec2(randf(P, z+0.3), randf(P, z+0.4)));
    n[2] = boxmuller(vec2(randf(P, z+0.5), randf(P, z+0.6)));

    // the weight to the green channel is due to the bayer order of a sensor.
    vec3 C_gaussian = vec3(n[0][0], n[1][0] * 0.7071, n[2][0]); // take first pair.
    vec3 C_V = pow(texture(iChannel0, c).rgb, vec3(2.4));

    C = vec4(pow(C_V + C_gaussian * exp2(-4.0), vec3(1.0/2.4)), 1.0);
}

// Generate Gold Noise sound
// box mullers too


vec2 mainSound( in int samp,float time)
{
    vec2 U = vec2(randf(vec2(iSampleRate*fract(time/100.0)), 1.0));
    vec2 G = boxmuller(U);

    return G;
}

// Gold Noise ©2015 dcerisano@standard3d.com
// - based on the Golden Ratio
// - uniform normalized distribution
// - fastest static noise generator function (also runs at low precision)
// - use with indicated fractional seeding method

const float PHI = 1.61803398874989484820459; // Φ = Golden Ratio 

float randf(in vec2 c, in float z)
{
    return fract(tan(distance(c*PHI, c)*z)*c.x);
}

const float PI = 3.1415926536;

vec2 boxmuller( in vec2 U )
{
    float theta = 2.0*PI*U[1];
    float R = sqrt(-2.0*log(U[0]));

    return clamp(vec2(R*cos(theta),R*sin(theta)), 0.0, 1.0);
}
